class Solution {
    public boolean isValid(String s) {
        boolean changed = true;
        while (changed) {
            changed = false;
            StringBuilder sb = new StringBuilder();
            int i = 0;
            while (i < s.length()) {
                if (i + 1 < s.length() && isPair(s.charAt(i), s.charAt(i + 1))) {
                    i += 2;       // 删掉这一对
                    changed = true;
                } else {
                    sb.append(s.charAt(i));
                    i++;
                }
            }
            s = sb.toString();
        }
        return s.isEmpty();
    }

    private boolean isPair(char a, char b) {
        return (a == '(' && b == ')')
            || (a == '[' && b == ']')
            || (a == '{' && b == '}');
    }
}

import java.util.*;

class Solution {
    public boolean isValid(String s) {
        Deque<Character> stack = new ArrayDeque<>();   // 比 Stack 快

        for (char c : s.toCharArray()) {
            if (c == '(' || c == '[' || c == '{') {
                stack.push(c);
            } else {
                // 栈空却遇到右括号：右括号多了
                if (stack.isEmpty()) return false;
                char top = stack.pop();
                if (!match(top, c)) return false;
            }
        }
        // 扫完还有剩余：左括号多了
        return stack.isEmpty();
    }

    private boolean match(char l, char r) {
        return (l == '(' && r == ')')
            || (l == '[' && r == ']')
            || (l == '{' && r == '}');
    }
}

class Solution {
    public boolean isValid(String s) {
        int n = s.length();
        if (n % 2 == 1) return false;   // 奇数长度一定不合法，快速返回

        char[] stack = new char[n];     // 手动栈，避免 Character 装箱
        int top = 0;

        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (c == '(') stack[top++] = ')';        // 直接存「期望的右括号」
            else if (c == '[') stack[top++] = ']';
            else if (c == '{') stack[top++] = '}';
            else {
                // 右括号：栈空或栈顶不匹配都不合法
                if (top == 0 || stack[--top] != c) return false;
            }
        }
        return top == 0;
    }
}
